void setup() {
  pinMode(9, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int syroe = analogRead(A0);
  int temperatura = map(syroe, 0, 1023, -20, 60);

  if (temperatura > 40 || temperatura < -10) {
    digitalWrite(9, HIGH);
    Serial.println("Авария");
  } else if (temperatura > 25) {
    digitalWrite(9, LOW);
    Serial.println("Предупреждение");
  } else {
    digitalWrite(9, LOW);
    Serial.println("Норма");
  }
  delay(300);
}
